package org.joda.time.field;

import java.io.*;
import java.math.*;
import java.util.*;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeFieldType;
import org.joda.time.IllegalFieldValueException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FieldUtils_safeMultiply_TriageGen2Test {

    @Test
    public void testSafeMultiply_CaseMinusOne() {
        assertEquals(-10L, FieldUtils.safeMultiply(10L, -1));
        assertEquals(10L, FieldUtils.safeMultiply(-10L, -1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, -1));
    }

    @Test
    public void testSafeMultiply_CaseZero() {
        assertEquals(0L, FieldUtils.safeMultiply(100L, 0));
        assertEquals(0L, FieldUtils.safeMultiply(-100L, 0));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 0));
    }

    @Test
    public void testSafeMultiply_CaseOne() {
        assertEquals(10L, FieldUtils.safeMultiply(10L, 1));
        assertEquals(-10L, FieldUtils.safeMultiply(-10L, 1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, 1));
    }

    @Test
    public void testSafeMultiply_NormalMultiplication() {
        assertEquals(20L, FieldUtils.safeMultiply(5L, 4));
        assertEquals(-20L, FieldUtils.safeMultiply(5L, -4));
        assertEquals(20L, FieldUtils.safeMultiply(-5L, -4));
        assertEquals(0L, FieldUtils.safeMultiply(10L, 0)); // Redundant but covers logic path
    }

    @Test
    public void testSafeMultiply_OverflowPositive() {
        try {
            // Long.MAX_VALUE is 9223372036854775807
            // Multiplying by 2 will definitely overflow
            FieldUtils.safeMultiply(Long.MAX_VALUE, 2);
            org.junit.Assert.fail("Expected ArithmeticException");
        } catch (ArithmeticException e) {
            assertEquals("Multiplication overflows a long: 9223372036854775807 * 2", e.getMessage());
        }
    }

    @Test
    public void testSafeMultiply_OverflowNegative() {
        try {
            // Long.MIN_VALUE is -9223372036854775808
            // Multiplying by 2 will definitely overflow
            FieldUtils.safeMultiply(Long.MIN_VALUE, 2);
            org.junit.Assert.fail("Expected ArithmeticException");
        } catch (ArithmeticException e) {
            assertEquals("Multiplication overflows a long: -9223372036854775808 * 2", e.getMessage());
        }
    }

    @Test
    public void testSafeMultiply_LargeValuesNoOverflow() {
        // Test values that are large but do not overflow a long
        long val1 = 1_000_000_000_000L;
        int val2 = 1_000_000;
        assertEquals(1_000_000_000_000_000_000L, FieldUtils.safeMultiply(val1, val2));
    }
}
